using System.ClientModel;
using System.ComponentModel;
using System.Text.Json;
using Microsoft.Extensions.AI;
using OpenAI;

// --- Configuration ---
var openAiKey = Environment.GetEnvironmentVariable("OPENAI_API_KEY")
    ?? throw new InvalidOperationException(
        "Set the OPENAI_API_KEY environment variable before running.");

var model = Environment.GetEnvironmentVariable("OPENAI_MODEL") ?? "gpt-4o-mini";

// --- Tools ---
var notebook = new Notebook();

var searchTool = AIFunctionFactory.Create(
    SearchWeb, "search_web", "Search the web for a query and return relevant results.");

var saveNoteTool = AIFunctionFactory.Create(
    notebook.SaveNote, "save_note", "Save a research note with a title and content.");

var getNotesTool = AIFunctionFactory.Create(
    notebook.GetNotes, "get_notes", "Retrieve all saved research notes.");

// --- Chat client with automatic function invocation ---
IChatClient client = new OpenAIClient(new ApiKeyCredential(openAiKey))
    .GetChatClient(model)
    .AsIChatClient()
    .AsBuilder()
    .UseFunctionInvocation()
    .Build();

var options = new ChatOptions
{
    Tools = [searchTool, saveNoteTool, getNotesTool],
    Temperature = 0.3f,
};

// --- Agent loop ---
Console.WriteLine("=== Research Agent ===");
Console.WriteLine("Enter a topic to research (or 'quit' to exit):\n");

while (true)
{
    Console.ForegroundColor = ConsoleColor.Cyan;
    Console.Write("> ");
    Console.ResetColor();

    var topic = Console.ReadLine()?.Trim();
    if (string.IsNullOrEmpty(topic) || topic.Equals("quit", StringComparison.OrdinalIgnoreCase))
        break;

    notebook.Clear();

    var messages = new List<ChatMessage>
    {
        new(ChatRole.System, """
            You are a research agent. Given a topic, you must:
            1. Search the web multiple times with varied queries to gather information.
            2. Save important findings as notes using the save_note tool.
            3. After gathering enough information (at least 3 searches), retrieve your
               notes with get_notes and produce a well-structured summary.
            Be thorough and cite your sources where possible.
            """),
        new(ChatRole.User, $"Research the following topic and provide a summary: {topic}"),
    };

    Console.WriteLine($"\nResearching \"{topic}\"...\n");

    try
    {
        var response = await client.GetResponseAsync(messages, options);

        Console.ForegroundColor = ConsoleColor.Green;
        Console.WriteLine("\n--- Research Summary ---\n");
        Console.ResetColor();
        Console.WriteLine(response.Text);
        Console.WriteLine();
    }
    catch (Exception ex)
    {
        Console.ForegroundColor = ConsoleColor.Red;
        Console.WriteLine($"\nError: {ex.Message}\n");
        Console.ResetColor();
    }
}

Console.WriteLine("Goodbye!");
return;

// --- Tool implementations ---

[Description("Search the web for a query and return relevant result snippets.")]
static async Task<string> SearchWeb(
    [Description("The search query")] string query)
{
    Console.ForegroundColor = ConsoleColor.DarkYellow;
    Console.WriteLine($"  🔍 Searching: \"{query}\"");
    Console.ResetColor();

    try
    {
        using var http = new HttpClient();
        http.DefaultRequestHeaders.UserAgent.ParseAdd(
            "Mozilla/5.0 (compatible; ResearchAgent/1.0)");

        // Use DuckDuckGo's HTML endpoint for a lightweight search
        var encoded = Uri.EscapeDataString(query);
        var url = $"https://html.duckduckgo.com/html/?q={encoded}";
        var html = await http.GetStringAsync(url);

        var results = ParseSearchResults(html);
        return results.Length > 0
            ? string.Join("\n\n", results.Take(5))
            : "No results found.";
    }
    catch (Exception ex)
    {
        return $"Search failed: {ex.Message}";
    }
}

static string[] ParseSearchResults(string html)
{
    var results = new List<string>();
    var snippetTag = "class=\"result__snippet\"";
    var titleTag = "class=\"result__a\"";
    var idx = 0;

    while (idx < html.Length && results.Count < 5)
    {
        var titleStart = html.IndexOf(titleTag, idx, StringComparison.Ordinal);
        if (titleStart < 0) break;

        var title = ExtractTagContent(html, titleStart);
        var snippetStart = html.IndexOf(snippetTag, titleStart, StringComparison.Ordinal);
        var snippet = snippetStart >= 0 ? ExtractTagContent(html, snippetStart) : "";

        if (!string.IsNullOrWhiteSpace(title))
            results.Add($"**{title.Trim()}**\n{snippet.Trim()}");

        idx = snippetStart >= 0 ? snippetStart + 1 : titleStart + 1;
    }

    return results.ToArray();
}

static string ExtractTagContent(string html, int attrPos)
{
    var gtPos = html.IndexOf('>', attrPos);
    if (gtPos < 0) return "";
    var closePos = html.IndexOf('<', gtPos + 1);
    if (closePos < 0) return "";
    return System.Net.WebUtility.HtmlDecode(html[(gtPos + 1)..closePos].Trim());
}

// --- Notebook ---
sealed class Notebook
{
    private readonly List<(string Title, string Content)> _notes = [];

    [Description("Save a research note.")]
    public string SaveNote(
        [Description("Short title for the note")] string title,
        [Description("Detailed content of the note")] string content)
    {
        _notes.Add((title, content));
        Console.ForegroundColor = ConsoleColor.DarkYellow;
        Console.WriteLine($"  📝 Note saved: \"{title}\"");
        Console.ResetColor();
        return $"Note \"{title}\" saved successfully. You now have {_notes.Count} note(s).";
    }

    [Description("Retrieve all saved research notes.")]
    public string GetNotes()
    {
        if (_notes.Count == 0)
            return "No notes saved yet.";

        Console.ForegroundColor = ConsoleColor.DarkYellow;
        Console.WriteLine($"  📖 Retrieving {_notes.Count} note(s)");
        Console.ResetColor();

        return string.Join("\n\n", _notes.Select((n, i) =>
            $"[Note {i + 1}] {n.Title}\n{n.Content}"));
    }

    public void Clear() => _notes.Clear();
}

